<template><div class="page"><el-card><template #header><div class="header"><div><b>自动化规则中心</b><small>用“当……如果……就……”组织个人流程，不需要配置 Cron</small></div><el-button type="primary" @click="open()">新建规则</el-button></div></template><div class="rules"><article v-for="rule in rules" :key="rule.id"><div class="rule-top"><div><b>{{rule.name}}</b><el-tag :type="statusType(rule.lastStatus)" size="small">{{statusText(rule.lastStatus)}}</el-tag></div><el-switch :model-value="rule.enabled" @change="toggle(rule,Boolean($event))"/></div><p><strong>当</strong> {{triggerName(rule.triggerType)}} <strong>如果</strong> 满足规则条件 <strong>就</strong> {{actionName(rule.actionType)}}</p><small>下次：{{rule.nextRunAt||'等待事件'}} · 最近：{{rule.lastRunAt||'尚未执行'}} · 冷却 {{rule.cooldownMinutes}} 分钟</small><div class="actions"><el-button @click="run(rule)">立即试运行</el-button><el-button @click="showLogs(rule)">执行日志</el-button><el-button @click="open(rule)">编辑</el-button><el-button type="danger" plain @click="remove(rule)">删除</el-button></div></article><el-empty v-if="!rules.length" description="创建第一条自动化规则"/></div></el-card>
<el-dialog v-model="visible" :title="editing?'编辑规则':'新建规则'" width="min(620px,94vw)"><el-form label-position="top"><el-form-item label="规则名称"><el-input v-model="form.name"/></el-form-item><div class="sentence"><b>当</b><el-select v-model="form.triggerType"><el-option v-for="x in triggers" :key="x.value" :label="x.label" :value="x.value"/></el-select><b>如果</b><el-input v-model="form.condition" placeholder="关键词、金额或提前分钟数"/><b>就</b><el-select v-model="form.actionType"><el-option v-for="x in actions" :key="x.value" :label="x.label" :value="x.value"/></el-select></div><el-form-item label="结果标题/内容"><el-input v-model="form.content" type="textarea" :rows="3"/></el-form-item><el-form-item label="冷却时间（分钟）"><el-input-number v-model="form.cooldownMinutes" :min="0"/></el-form-item><el-checkbox v-model="form.enabled">立即启用</el-checkbox></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog>
<el-drawer v-model="logsVisible" title="执行日志" size="min(620px,94vw)"><article v-for="x in logs" :key="x.id" class="log"><el-tag :type="statusType(x.status)">{{statusText(x.status)}}</el-tag><b>{{x.sourceType||'SCHEDULE'}} #{{x.sourceId||'-'}}</b><small>{{x.startedAt}} · 尝试 {{x.attemptCount}} 次</small><p v-if="x.failureReason">{{x.failureReason}}</p></article><el-empty v-if="!logs.length" description="暂无执行日志"/></el-drawer></div></template>
<script setup lang="ts">import{ElMessage,ElMessageBox}from'element-plus';import{onMounted,reactive,ref}from'vue';import{createRule,deleteRule,listExecutions,listRules,runRule,toggleRule,updateRule,type AutomationExecution,type AutomationRule}from'@/api/automation';const rules=ref<AutomationRule[]>([]),logs=ref<AutomationExecution[]>([]),visible=ref(false),logsVisible=ref(false),editing=ref<AutomationRule>();const triggers=[['TASK_DUE','任务即将到期'],['TASK_OVERDUE','任务已经逾期'],['INBOX_KEYWORD','收件箱出现关键词'],['BILL_THRESHOLD','账单达到金额阈值'],['UNCATEGORIZED_BILL','未分类账单持续存在'],['FIXED_TIME','每天固定时间'],['WORKDAY_TIME','工作日固定时间']].map(([value,label])=>({value,label}));const actions=[['CREATE_REMINDER','创建提醒'],['CREATE_TASK','创建任务'],['SEND_NOTIFICATION','发送现有通知'],['GENERATE_REPORT','生成自动报告'],['ADD_INBOX','添加收件箱记录']].map(([value,label])=>({value,label}));const form=reactive({name:'',enabled:true,triggerType:'TASK_DUE',condition:'60',actionType:'CREATE_REMINDER',content:'',cooldownMinutes:60});async function load(){rules.value=(await listRules()).data;}function open(rule?:AutomationRule){editing.value=rule;if(rule)Object.assign(form,{name:rule.name,enabled:rule.enabled,triggerType:rule.triggerType,condition:'',actionType:rule.actionType,content:'',cooldownMinutes:rule.cooldownMinutes});else Object.assign(form,{name:'',enabled:true,triggerType:'TASK_DUE',condition:'60',actionType:'CREATE_REMINDER',content:'',cooldownMinutes:60});visible.value=true;}async function save(){if(!form.name.trim()){ElMessage.warning('请输入规则名称');return;}const numeric=Number(form.condition)||0;const triggerConfig=form.triggerType==='INBOX_KEYWORD'?{keyword:form.condition}:form.triggerType==='BILL_THRESHOLD'?{amount:numeric}:form.triggerType==='UNCATEGORIZED_BILL'?{days:numeric}:form.triggerType.includes('TIME')?{time:form.condition||'09:00'}:{minutes:numeric};const payload={name:form.name,enabled:form.enabled,triggerType:form.triggerType,triggerConfig,conditionConfig:{},actionType:form.actionType,actionConfig:{title:form.content||form.name,content:form.content||form.name,category:'自动化'},cooldownMinutes:form.cooldownMinutes};if(editing.value)await updateRule(editing.value.id,payload);else await createRule(payload);visible.value=false;ElMessage.success('规则已保存');await load();}async function toggle(rule:AutomationRule,enabled:boolean){await toggleRule(rule.id,enabled);await load();}async function run(rule:AutomationRule){await runRule(rule.id);ElMessage.success('试运行完成');await load();}async function showLogs(rule:AutomationRule){logs.value=(await listExecutions(rule.id)).data;logsVisible.value=true;}async function remove(rule:AutomationRule){await ElMessageBox.confirm('删除规则不会删除历史日志和已创建的业务记录，确定删除？','删除规则');await deleteRule(rule.id);await load();}const triggerName=(v:string)=>triggers.find(x=>x.value===v)?.label||v;const actionName=(v:string)=>actions.find(x=>x.value===v)?.label||v;const statusText=(v?:string)=>({SUCCESS:'成功',FAILED:'失败',SKIPPED:'已跳过',RUNNING:'执行中'}[v||'']||'未执行');const statusType=(v?:string)=>v==='SUCCESS'?'success':v==='FAILED'?'danger':'info';onMounted(load);</script>
<style scoped>.page{display:flex;flex-direction:column;gap:14px}.header,.rule-top{display:flex;align-items:center;justify-content:space-between;gap:12px}.header small{display:block;margin-top:4px;color:#718096}.rules{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}.rules article{padding:18px;border:1px solid #e4eaf2;border-radius:14px}.rule-top>div{display:flex;gap:8px}.rules p{line-height:1.9}.rules p strong{color:#5275f5}.rules small,.log small{display:block;color:#718096}.actions{display:flex;flex-wrap:wrap;gap:7px;margin-top:15px}.sentence{display:grid;grid-template-columns:auto 1fr auto 1fr auto 1fr;align-items:center;gap:8px;margin:16px 0}.sentence>b{color:#5275f5}.log{display:flex;flex-direction:column;gap:8px;margin-bottom:12px;padding:14px;border:1px solid #e5eaf1;border-radius:12px}.log p{color:#d44}@media(max-width:768px){.rules{grid-template-columns:1fr}.sentence{grid-template-columns:auto 1fr}.header{align-items:flex-start;flex-direction:column}}</style>
